import * as React from "react";
import {
  Card,
  Box,
  BlockStack,
  InlineStack,
  Text,
  Button,
} from "@xco-agency/corex-ui";
import type { AppCrossSellPropsType } from "./types";
import { DEFAULT_APPS_LIST, DEFAULT_DISCOUNT_TIERS } from "./constants";
import { AppCrossSellTierProgress } from "./partials/AppCrossSellTierProgress";
import { AppCrossSellRow } from "./partials/AppCrossSellRow";

export function AppCrossSell({
  title = "Get more from every customer and save up to 30%",
  description = "The more apps you install, the higher your revenue, the bigger your discount on all of them.",
  tiers = DEFAULT_DISCOUNT_TIERS,
  apps = DEFAULT_APPS_LIST,
  onInstall,
  onDismiss,
  installedCount,
}: AppCrossSellPropsType) {
  const [showAll, setShowAll] = React.useState(false);

  const currentInstalledCount =
    installedCount !== undefined
      ? installedCount
      : apps.filter((app) => app.installed).length;

  // Compute next unlockable discount percentage
  const nextDiscount =
    currentInstalledCount < 2 ? "10%" : currentInstalledCount < 3 ? "20%" : "30%";

  const displayedApps = showAll ? apps : apps.slice(0, 5);

  return (
    <Card>
      <BlockStack gap="base">
        {/* Header with Title, Description, and Close Button */}
        <InlineStack justifyContent="space-between" alignItems="flex-start" gap="base">
          <BlockStack gap="small-300">
            <Text variant="headingMd" as="h2" fontWeight="bold">
              {title}
            </Text>
            <Text variant="bodySm" tone="subdued" as="p">
              {description}
            </Text>
          </BlockStack>

          {onDismiss && (
            <Button
              variant="tertiary"
              icon="cancel"
              accessibilityLabel="Dismiss promotion"
              onClick={onDismiss}
            />
          )}
        </InlineStack>

        {/* Milestone Discount Stepper */}
        <AppCrossSellTierProgress
          tiers={tiers}
          installedCount={currentInstalledCount}
        />

        {/* Bordered Apps Container */}
        <Box
          borderWidth="small-100"
          borderColor="border"
          borderRadius="base"
          background="bg-surface"
          overflow="hidden"
        >
          {displayedApps.map((app, index) => {
            const formattedApp = {
              ...app,
              unlockDiscountText:
                app.unlockDiscountText || `Install to unlock ${nextDiscount} off`,
            };

            return (
              <AppCrossSellRow
                key={app.id}
                app={formattedApp}
                onInstall={onInstall}
                isLast={index === displayedApps.length - 1 && (!apps.length || apps.length <= 5 || showAll)}
              />
            );
          })}

          {apps.length > 5 && (
            <Box
              padding="small-200 base"
              borderBlockStartWidth="small-100"
              borderColor="border-subdued"
              background="bg-surface-secondary"
            >
              <InlineStack justifyContent="center">
                <Button variant="tertiary" onClick={() => setShowAll(!showAll)}>
                  {showAll ? "Show fewer apps" : `View all ${apps.length} available apps`}
                </Button>
              </InlineStack>
            </Box>
          )}
        </Box>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  Box,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
} from "@xco-agency/corex-ui";
import { AppIconBadge } from "../partials/AppIconBadge";
import { DEFAULT_APPS_LIST } from "../constants";
import type { AppCrossSellItemType } from "../types";

export function AppCrossSellCompactExample() {
  const [apps, setApps] = React.useState<AppCrossSellItemType[]>(
    DEFAULT_APPS_LIST.slice(0, 3)
  );

  const handleInstall = (id: string) => {
    setApps((current) =>
      current.map((a) => (a.id === id ? { ...a, installed: true } : a))
    );
  };

  const installedCount = apps.filter((a) => a.installed).length;

  return (
    <Box maxInlineSize="440px">
      <Card>
        <BlockStack gap="base">
          {/* Header */}
          <InlineStack justifyContent="space-between" alignItems="center">
            <BlockStack gap="small-500">
              <Text variant="headingSm" as="h3" fontWeight="bold">
                Ecosystem Partner Apps
              </Text>
              <Text variant="bodySm" tone="subdued">
                Save up to 30% by installing complementary apps
              </Text>
            </BlockStack>
            <Badge tone="success">Up to 30% off</Badge>
          </InlineStack>

          {/* Mini Tier Indicator */}
          <Box
            padding="small-200 base"
            background="bg-surface-secondary"
            borderRadius="small"
          >
            <InlineStack justifyContent="space-between" alignItems="center">
              <Text variant="bodySm" tone="subdued">
                {installedCount} of 3 active on store
              </Text>
              <Text variant="bodySm" fontWeight="semibold" tone="success">
                {installedCount >= 2 ? "15% Discount Active" : "Install 1 more for 10% off"}
              </Text>
            </InlineStack>
          </Box>

          {/* Compact App Rows */}
          <Box
            borderWidth="small-100"
            borderColor="border"
            borderRadius="base"
            overflow="hidden"
          >
            {apps.map((app, index) => (
              <Box
                key={app.id}
                padding="small-200 base"
                borderBlockEndWidth={index < apps.length - 1 ? "small-100" : "none"}
                borderColor="border-subdued"
                background="bg-surface"
              >
                <InlineStack justifyContent="space-between" alignItems="center" gap="base">
                  <InlineStack gap="small-300" alignItems="center">
                    <AppIconBadge
                      type={app.iconType}
                      bg={app.iconBg}
                      name={app.name}
                      size={32}
                    />

                    <BlockStack gap="none">
                      <Text variant="bodySm" fontWeight="semibold" truncate>
                        {app.name}
                      </Text>
                      <Text variant="bodySm" tone="subdued" truncate>
                        {app.category}
                      </Text>
                    </BlockStack>
                  </InlineStack>

                  <InlineStack shrink={false}>
                    {app.installed ? (
                      <Badge tone="success" size="small">
                        Installed
                      </Badge>
                    ) : (
                      <Button
                        size="small"
                        variant="secondary"
                        onClick={() => handleInstall(app.id)}
                      >
                        Install
                      </Button>
                    )}
                  </InlineStack>
                </InlineStack>
              </Box>
            ))}
          </Box>

          {/* Footer Link */}
          <InlineStack justifyContent="center">
            <Button variant="tertiary">
              View all 15 partner apps &rarr;
            </Button>
          </InlineStack>
        </BlockStack>
      </Card>
    </Box>
  );
}

import * as React from "react";
import { Box, BlockStack, InlineStack, Button, Text } from "@xco-agency/corex-ui";
import { AppCrossSell } from "../AppCrossSell";
import { DEFAULT_APPS_LIST, DEFAULT_DISCOUNT_TIERS } from "../constants";
import type { AppCrossSellItemType } from "../types";

export function AppCrossSellExample() {
  const [apps, setApps] = React.useState<AppCrossSellItemType[]>(DEFAULT_APPS_LIST);
  const [isDismissed, setIsDismissed] = React.useState(false);

  const installedCount = apps.filter((a) => a.installed).length;

  const handleInstall = (appId: string) => {
    setApps((current) =>
      current.map((app) => (app.id === appId ? { ...app, installed: true } : app))
    );
  };

  const handleReset = () => {
    setApps(DEFAULT_APPS_LIST);
    setIsDismissed(false);
  };

  return (
    <BlockStack gap="base">
      {!isDismissed ? (
        <AppCrossSell
          apps={apps}
          tiers={DEFAULT_DISCOUNT_TIERS}
          installedCount={installedCount}
          onInstall={handleInstall}
          onDismiss={() => setIsDismissed(true)}
        />
      ) : (
        <Box
          padding="base"
          background="subdued"
          borderRadius="base"
        >
          <InlineStack justifyContent="space-between" alignItems="center">
            <Text color="subdued">Cross-sell promotion banner was dismissed.</Text>
            <Button variant="secondary" onClick={() => setIsDismissed(false)}>
              Restore Banner
            </Button>
          </InlineStack>
        </Box>
      )}

      {/* Demo Controls */}
      <InlineStack justifyContent="space-between" alignItems="center">
        <Text variant="bodySm" color="subdued">
          Interactive demo: Click &quot;Install&quot; on any app to unlock higher discounts ({installedCount} of {apps.length} active).
        </Text>
        <Button variant="tertiary" onClick={handleReset}>
          Reset Apps State
        </Button>
      </InlineStack>
    </BlockStack>
  );
}

import * as React from "react";
import {
  Card,
  Box,
  BlockStack,
  InlineStack,
  Grid,
  Text,
  Badge,
  Button,
} from "@xco-agency/corex-ui";
import { AppIconBadge } from "../partials/AppIconBadge";
import { AppCrossSellTierProgress } from "../partials/AppCrossSellTierProgress";
import { DEFAULT_APPS_LIST, DEFAULT_DISCOUNT_TIERS } from "../constants";
import type { AppCrossSellItemType } from "../types";

export function AppCrossSellGridExample() {
  const [apps, setApps] = React.useState<AppCrossSellItemType[]>(DEFAULT_APPS_LIST);

  const installedCount = apps.filter((a) => a.installed).length;
  const displayedApps = apps.slice(0, 6);

  const handleInstall = (id: string) => {
    setApps((current) =>
      current.map((a) => (a.id === id ? { ...a, installed: true } : a))
    );
  };

  return (
    <BlockStack gap="base">
      <Card>
        <BlockStack gap="base">
          {/* Header */}
          <BlockStack gap="small-300">
            <Text variant="headingMd" as="h2" fontWeight="bold">
              Get more from every customer and save up to 30%
            </Text>
            <Text variant="bodySm" tone="subdued" as="p">
              The more apps you install, the higher your revenue, the bigger your discount on all of them.
            </Text>
          </BlockStack>

          {/* Stepper progress */}
          <AppCrossSellTierProgress
            tiers={DEFAULT_DISCOUNT_TIERS}
            installedCount={installedCount}
          />

          {/* 3-Column App Cards Grid */}
          <Grid columns={{ sm: 1, md: 2, lg: 3 }} gap="base">
            {displayedApps.map((app) => (
              <Box
                key={app.id}
                borderWidth="small-100"
                borderColor="border"
                borderRadius="base"
                padding="base"
                background="bg-surface"
              >
                <BlockStack gap="base">
                  <BlockStack gap="small-300">
                    <InlineStack justifyContent="space-between" alignItems="flex-start">
                      <AppIconBadge
                        type={app.iconType}
                        bg={app.iconBg}
                        name={app.name}
                        size={44}
                      />

                      {app.installed ? (
                        <Badge tone="success" size="small">
                          Installed
                        </Badge>
                      ) : app.builtForShopify ? (
                        <Badge tone="info" size="small">
                          Built for Shopify
                        </Badge>
                      ) : null}
                    </InlineStack>

                    <BlockStack gap="small-500">
                      <Text variant="bodyMd" fontWeight="bold">
                        {app.name}
                      </Text>

                      {app.rating && (
                        <InlineStack gap="small-400" alignItems="center">
                          <Text variant="bodySm" fontWeight="semibold">
                            ★ {app.rating.toFixed(1)}
                          </Text>
                          {app.reviewsCount && (
                            <Text variant="bodySm" tone="subdued">
                              ({app.reviewsCount})
                            </Text>
                          )}
                          {app.pricingBadge && (
                            <Text variant="bodySm" tone="subdued">
                              • {app.pricingBadge}
                            </Text>
                          )}
                        </InlineStack>
                      )}
                    </BlockStack>

                    <Text variant="bodySm" tone="subdued" as="p">
                      {app.category}
                    </Text>
                  </BlockStack>

                  <Box
                    borderBlockStartWidth="small-100"
                    borderColor="border-subdued"
                    paddingBlockStart="small-200"
                  >
                    {app.installed ? (
                      <Button fullWidth disabled>
                        Installed on store
                      </Button>
                    ) : (
                      <Button
                        fullWidth
                        variant="primary"
                        onClick={() => handleInstall(app.id)}
                      >
                        {app.unlockDiscountText || "Install app"}
                      </Button>
                    )}
                  </Box>
                </BlockStack>
              </Box>
            ))}
          </Grid>
        </BlockStack>
      </Card>
    </BlockStack>
  );
}

export { AppCrossSell } from "./AppCrossSell";
export { AppCrossSellExample } from "./examples/AppCrossSellExample";
export { AppCrossSellGridExample } from "./examples/AppCrossSellGridExample";
export { AppCrossSellCompactExample } from "./examples/AppCrossSellCompactExample";
export * from "./types";
export * from "./constants";

import * as React from "react";
import { Box, BlockStack, InlineStack, Text, Badge, Button } from "@xco-agency/corex-ui";
import type { AppCrossSellItemType } from "../types";
import { AppIconBadge } from "./AppIconBadge";

export type AppCrossSellRowPropsType = {
  app: AppCrossSellItemType;
  onInstall?: (id: string) => void;
  isLast?: boolean;
};

export function AppCrossSellRow({
  app,
  onInstall,
  isLast = false,
}: AppCrossSellRowPropsType) {
  return (
    <Box
      padding="small-200 base"
      borderBlockEndWidth={isLast ? "none" : "small-100"}
      borderColor="border-subdued"
    >
      <InlineStack justifyContent="space-between" alignItems="center" gap="base">
        {/* App identity */}
        <InlineStack gap="base" alignItems="center">
          <AppIconBadge
            type={app.iconType}
            bg={app.iconBg}
            logoUrl={app.logoUrl}
            name={app.name}
            size={38}
          />
          <BlockStack gap="small-500">
            <InlineStack gap="small-200" alignItems="center" wrap>
              <Text variant="base" fontWeight="semibold">
                {app.name}
              </Text>
              {app.builtForShopify && (
                <Badge tone="info" size="small">
                  Built for Shopify
                </Badge>
              )}
            </InlineStack>
            {app.category && (
              <Text variant="xs" tone="subdued">
                {app.category}
              </Text>
            )}
          </BlockStack>
        </InlineStack>

        {/* Action / Status */}
        <InlineStack shrink={false}>
          {app.installed ? (
            <Badge tone="success" size="base">
              Installed
            </Badge>
          ) : (
            <Button
              variant="secondary"
              onClick={() => onInstall?.(app.id)}
            >
              {app.unlockDiscountText || "Install to unlock 30% off"}
            </Button>
          )}
        </InlineStack>
      </InlineStack>
    </Box>
  );
}

import * as React from "react";
import { Box, InlineStack, Text, Icon } from "@xco-agency/corex-ui";
import type { DiscountTierType } from "../types";

export type AppCrossSellTierProgressPropsType = {
  tiers: DiscountTierType[];
  installedCount?: number;
};

export function AppCrossSellTierProgress({
  tiers,
  installedCount = 1,
}: AppCrossSellTierProgressPropsType) {
  return (
    <InlineStack justifyContent="space-between" alignItems="center" gap="small-200" wrap>
      {tiers.map((tier, index) => {
        const isReached = installedCount >= tier.appsCount;

        return (
          <React.Fragment key={tier.id}>
            <Box
              background={isReached ? "bg-surface-secondary" : "bg-surface"}
              borderWidth="small-100"
              borderColor={isReached ? "border" : "border-subdued"}
              borderRadius="large-100"
              padding="small-200 base"
            >
              <Text
                variant="bodySm"
                fontWeight={isReached ? "semibold" : "medium"}
                tone={isReached ? "success" : "subdued"}
              >
                {tier.label}
              </Text>
            </Box>

            {index < tiers.length - 1 && (
              <Icon type="arrow-right" tone="subdued" />
            )}
          </React.Fragment>
        );
      })}
    </InlineStack>
  );
}

export type AppCrossSellItemType = {
  id: string;
  name: string;
  category?: string;
  installed: boolean;
  iconBg?: string;
  iconType?: string;
  logoUrl?: string;
  unlockDiscountText?: string;
  appUrl?: string;
  rating?: number;
  reviewsCount?: number;
  pricingBadge?: string;
  builtForShopify?: boolean;
};

export type DiscountTierType = {
  id: string;
  appsCount: number;
  discountPercent: number;
  label: string;
};

export type AppCrossSellPropsType = {
  title?: string;
  description?: string;
  tiers?: DiscountTierType[];
  apps?: AppCrossSellItemType[];
  onInstall?: (appId: string) => void;
  onDismiss?: () => void;
  installedCount?: number;
};
